args.code:
const tabId = 103795513;
const zeddEvents = await browserjs(tabId, () => {
  // Find all seated event rows or elements
  const results = [];
  const links = Array.from(document.querySelectorAll('a[href*="seated.com"]'));
  for (const a of links) {
    // get parent container
    let container = a.parentElement;
    for (let i = 0; i < 4; i++) {
      if (container && container.innerText.includes('\n')) break;
      if (container) container = container.parentElement;
    }
    results.push({
      text: container ? container.innerText : a.innerText,
      link: a.href
    });
  }
  return results;
});
console.log("Zedd events parsed:", JSON.stringify(zeddEvents, null, 2));

