  return await browserjs(tabId, () => {
    // Get text lines around flights
    const text = document.body.innerText;
    const topSection = text.slice(text.indexOf('Top flights') !== -1 ? text.indexOf('Top flights') : text.indexOf('Top departing flights'), (text.indexOf('Top flights') !== -1 ? text.indexOf('Top flights') : text.indexOf('Top departing flights')) + 1500);
    return topSection;
  });
};

