const tabId = 103795517;
const hotels = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('[data-testid="property-card"]'));
  return cards.slice(0, 5).map(c => {
    const titleEl = c.querySelector('[data-testid="title"]');
    const priceEl = c.querySelector('[data-testid="price-and-discounted-price"]');
    const linkEl = c.querySelector('a[data-testid="title-link"]');
    const scoreEl = c.querySelector('[data-testid="review-score"]');
